function _closeSlide(){$('ctc-slide-panel')?.classList.remove('panel-open');overlay?.classList.remove('visible');_setFab(!1);panelOpen=!1}
function _toggleBadge(){const pop=$('ctc-badge-popup');if(!pop)return;if(pop.classList.contains('open')){pop.classList.remove('open');panelOpen=!1;return}
pop.innerHTML=panelBody();pop.classList.add('open');panelOpen=!0}
function _toggleDock(){const pop=$('ctc-dock-popup');if(!pop)return;if(pop.classList.contains('open')){pop.classList.remove('open');$('ctc-dock-main')?.classList.remove('fab-open');panelOpen=!1;return}
pop.innerHTML=panelBody();pop.classList.add('open');$('ctc-dock-main')?.classList.add('fab-open');panelOpen=!0}
function _openToolbar(){$('ctc-toolbar')?.classList.remove('toolbar-collapsed');$('ctc-toolbar-collapsed-tab')?.classList.remove('visible');panelOpen=!0}
function _closeToolbar(){$('ctc-toolbar')?.classList.add('toolbar-collapsed');$('ctc-toolbar-collapsed-tab')?.classList.add('visible');panelOpen=!1}
